module TestTraits

using Test
using H2Factory

# `maptrait(A)` forwards to `maptrait(typeof(A))`, and that forward has to TERMINATE. Before the
# type-level method existed it did not: `typeof(A)` for an undeclared `A` is a `DataType`, which
# matches the untyped method again, and `typeof(DataType)` is `DataType`, so the call recursed on
# itself until the stack was gone.
#
# The reach of that is narrower than it first looks, and these assertions are scoped to the real one.
# The thirty accessors generated by `@traitaccessor` type their 1-arg method `A::AbstractH2Maps`, so
# a non-map never reached `maptrait` through them; they answered with a `MethodError` then and now.
# The recursion was reachable through direct `maptrait`/`forwardmap` calls, and through callers that
# did not restrict their argument type, which is what `testmomentcollections` and
# `trialmomentcollections` were before they were typed.
struct UndeclaredMap end

# eltype matters here, and not decoratively: `LinearMaps` folds `adjoint` into a `TransposeMap`
# when the eltype is REAL, because adjoint and transpose coincide there. A `Float64` test map
# therefore never reaches the `isAdjoint` branch at all, and a test written only against one would
# silently cover two thirds of the trait space.
struct DeclaredMap{T} <: H2Factory.AbstractH2Map{T} end

@testset verbose = true "map orientation traits" begin
    @testset "an undeclared type is refused, not recursed" begin
        # Both entry points: the value forward and the type method it forwards to.
        @test_throws ArgumentError H2Factory.maptrait(UndeclaredMap())
        @test_throws ArgumentError H2Factory.maptrait(UndeclaredMap)
        @test_throws ArgumentError H2Factory.forwardmap(UndeclaredMap())

        # The message has to name the offending type, since the recursion used to hide it and the
        # report landed on whichever accessor happened to be called.
        err = try
            H2Factory.maptrait(UndeclaredMap())
            nothing
        catch e
            e
        end
        @test err isa ArgumentError
        @test occursin("UndeclaredMap", err.msg)
        @test occursin("maptrait", err.msg)
    end

    @testset "accessors refuse a non-map with a MethodError" begin
        # The reported symptom was an accessor, not `maptrait`: a core passed where a map belongs.
        # `@traitaccessor` types its 1-arg method `A::AbstractH2Maps`, so its thirty accessors have
        # always answered this with a clean `MethodError`. `trialmomentcollections` and
        # `testmomentcollections` were written by hand with an UNTYPED `A`, accepted the core, and
        # recursed inside `maptrait`; they are now restricted to match, so all of these agree.
        for accessor in (
            H2Factory.trialmomentcollections,
            H2Factory.testmomentcollections,
            H2Factory.trialmoments,
            H2Factory.testmoments,
            H2Factory.trialmoment,
        )
            @test_throws MethodError accessor(UndeclaredMap())
        end

        # The 2-arg form is how a core is legitimately reached, so restricting the 1-arg form must
        # not have touched it. iFMM's `_adjointleafmul` depends on exactly this call shape.
        @test hasmethod(
            H2Factory.testmomentcollections,
            Tuple{H2Factory.GalerkinH2Map,H2Factory.isForward},
        )
        @test hasmethod(
            H2Factory.trialmomentcollections,
            Tuple{H2Factory.GalerkinH2Map,H2Factory.isForward},
        )
        # And a workspace still resolves through the 1-arg form, since `AbstractH2Workspace` is
        # inside `AbstractH2Maps`. If that ever stops holding, `diagnostics/structure.jl` breaks.
        @test H2Factory.AbstractH2Workspace <: H2Factory.AbstractH2Maps
    end

    @testset "declared maps and wrapper unwrapping are unchanged" begin
        # The negative control for the fallback: it must be less specific than every real
        # declaration, so nothing that worked before changes.
        for T in (Float64, ComplexF64)
            m = DeclaredMap{T}()
            @test H2Factory.maptrait(m) == H2Factory.isForward()
            @test H2Factory.maptrait(transpose(m)) == H2Factory.isTranspose()
            @test H2Factory.forwardmap(m) === m
            @test H2Factory.forwardmap(transpose(m)) === m
            @test H2Factory.forwardmap(adjoint(m)) === m
        end

        # Split by eltype for the reason given above: only the complex map produces an `AdjointMap`.
        @test H2Factory.maptrait(adjoint(DeclaredMap{ComplexF64}())) ==
            H2Factory.isAdjoint()
        @test H2Factory.maptrait(adjoint(DeclaredMap{Float64}())) == H2Factory.isTranspose()
    end
end

end
